-- Données de démonstration publiques pour le site Petna.
-- Ce fichier contient uniquement des commandes LMD (INSERT ... ON CONFLICT).
-- Réexécutable sans créer de doublons grâce aux identifiants stables.

insert into public.animals (
  id, name, species, age, city, shelter, image_url, summary,
  temperament, care, adoption_conditions, status
) values
  ('00000000-0000-4000-8000-000000000001', 'Luna', 'Chat', '8 mois', 'Tunis', 'Association Patte Solidaire', 'https://images.unsplash.com/photo-1573865526739-10659fec78a5?auto=format&fit=crop&w=800&q=80', 'Curieuse et douce, elle adore les siestes au soleil.', 'Sociable, joueuse et très câline après un petit temps d’adaptation.', 'Vie en intérieur recommandée. Vaccinée et identifiée selon les informations du refuge.', 'Rencontre préalable avec l’association et engagement à lui offrir un foyer stable.', 'published'),
  ('00000000-0000-4000-8000-000000000002', 'Oscar', 'Chien', '2 ans', 'Sousse', 'Refuge Les Amis des Animaux', 'https://images.unsplash.com/photo-1552053831-71594a27632d?auto=format&fit=crop&w=800&q=80', 'Un compagnon fidèle qui aime les longues promenades.', 'Équilibré, proche des humains et à l’aise avec les promenades actives.', 'A besoin d’exercice quotidien et d’un espace confortable pour se reposer.', 'Échange avec le refuge et rencontre avant toute décision.', 'published'),
  ('00000000-0000-4000-8000-000000000003', 'Mimi', 'Chat', '1 an', 'La Marsa', 'Association Patte Solidaire', 'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?auto=format&fit=crop&w=800&q=80', 'Petite exploratrice, tranquille et facile à vivre.', 'Indépendante mais affectueuse, elle apprécie les endroits calmes.', 'Adaptée à la vie en appartement sécurisé. Routine et jeux doux conseillés.', 'Adoption après discussion avec les bénévoles de l’association.', 'published'),
  ('00000000-0000-4000-8000-000000000004', 'Pistache', 'Lapin', '6 mois', 'Tunis', 'Refuge Les Petits Compagnons', 'https://images.unsplash.com/photo-1585110396000-c9ffd4e4b308?auto=format&fit=crop&w=800&q=80', 'Un petit gourmand paisible qui aime prendre son temps.', 'Doux et observateur, il se laisse apprivoiser avec patience.', 'Foin à volonté, espace sécurisé et suivi adapté aux lapins.', 'Le refuge accompagne la famille sur les besoins spécifiques de l’espèce.', 'published'),
  ('00000000-0000-4000-8000-000000000005', 'Bella', 'Chien', '1 an', 'Monastir', 'Les Pattes de Monastir', 'https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&w=800&q=80', 'Douce et sociable, elle aime les promenades au bord de l’eau.', 'Affectueuse, attentive et enthousiaste lors des sorties.', 'Balades quotidiennes et jeux de flair l’aident à s’épanouir.', 'Rencontre avec les bénévoles et échange sur son futur cadre de vie.', 'published'),
  ('00000000-0000-4000-8000-000000000006', 'Rocky', 'Chien', '3 ans', 'Nabeul', 'Les Pattes de Nabeul', 'https://images.unsplash.com/photo-1548199973-03cce0bbc87b?auto=format&fit=crop&w=800&q=85', 'Joyeux et attentif, il aime apprendre de nouveaux jeux.', 'Sociable avec les personnes et plein d’énergie en extérieur.', 'Balades régulières et activités de stimulation recommandées.', 'Entretien avec l’association et rencontre dans son environnement.', 'published')
on conflict (id) do update set
  name = excluded.name, species = excluded.species, age = excluded.age,
  city = excluded.city, shelter = excluded.shelter, image_url = excluded.image_url,
  summary = excluded.summary, temperament = excluded.temperament, care = excluded.care,
  adoption_conditions = excluded.adoption_conditions, status = excluded.status;

