  ('00000000-0000-4000-8000-000000000105', 'Duo de bols en céramique', 'Accessoires', 27.00, 'Moustache & Cie', 'assets/products/duo-bols-ceramique.png', 'Deux bols faciles à nettoyer, avec base stable antidérapante.', false, 'published'),
  ('00000000-0000-4000-8000-000000000106', 'Litière végétale agglomérante', 'Hygiène', 22.00, 'Maison Toutou', 'assets/products/litiere-vegetale.png', 'Litière à base de fibres végétales, légère et simple à entretenir.', false, 'published'),
  ('00000000-0000-4000-8000-000000000107', 'Biscuits pomme & avoine', 'Alimentation', 11.90, 'Moustache & Cie', 'assets/products/biscuits-pomme-avoine.png', 'Petites friandises croquantes pour récompenser les bons moments.', false, 'published'),
  ('00000000-0000-4000-8000-000000000108', 'Croquettes saumon pour chat', 'Alimentation', 28.00, 'Maison Toutou', 'assets/products/croquettes-saumon-chat.jpg', 'Croquettes complètes au saumon pour chat adulte, format 1,5 kg.', false, 'published'),
