  ('00000000-0000-4000-8000-000000000110', 'Tapis de repos moelleux', 'Accessoires', 45.00, 'Le Comptoir des Pattes', 'assets/products/tapis-repos-moelleux.png', 'Coussin doux avec housse facile à retirer pour le lavage.', false, 'published'),
  ('00000000-0000-4000-8000-000000000111', 'Shampoing doux avoine', 'Hygiène', 19.50, 'Maison Toutou', 'assets/products/shampoing-doux-avoine.png', 'Soin lavant doux pour le pelage, à utiliser selon les conseils du vétérinaire.', false, 'published'),
  ('00000000-0000-4000-8000-000000000112', 'Sac de transport pliable', 'Accessoires', 58.00, 'Moustache & Cie', 'assets/products/sac-transport-pliable.png', 'Sac aéré pour les petits trajets et les visites de routine.', false, 'published')
on conflict (id) do update set
