insert into public.providers (id, name, type, city, image_url, description, services, hours, contact, status) values
  ('00000000-0000-4000-8000-000000000201', 'Clinique Vétérinaire du Nord', 'Vétérinaire', 'La Marsa', 'https://images.unsplash.com/photo-1628009368231-7bb7cfcb0def?auto=format&fit=crop&w=700&q=80', 'Soins de proximité et conseils de prévention pour chiens et chats.', array['Consultation générale — dès 45 TND','Vaccination — dès 35 TND','Conseils nutritionnels'], 'Lun–Sam · 08:30–18:00', '+216 70 000 101', 'published'),
  ('00000000-0000-4000-8000-000000000202', 'Moustache & Cie', 'Animalerie', 'Tunis', 'https://images.unsplash.com/photo-1583337130417-3346a1be7dee?auto=format&fit=crop&w=700&q=80', 'Une sélection attentive de produits et accessoires pour vos compagnons.', array['Alimentation et accessoires','Conseils en magasin','Retrait en boutique'], 'Lun–Sam · 09:00–19:00', '+216 71 000 202', 'published'),
  ('00000000-0000-4000-8000-000000000203', 'Le Bain des Toutous', 'Toilettage', 'Sousse', 'assets/providers/le-bain-des-toutous.png', 'Toilettage doux adapté au pelage et au tempérament de chaque chien.', array['Bain et séchage — dès 35 TND','Brossage — dès 20 TND','Conseils d’entretien'], 'Mar–Sam · 09:00–17:30', '+216 73 000 303', 'published'),
  ('00000000-0000-4000-8000-000000000204', 'Clinique des Jardins', 'Vétérinaire', 'Ariana', 'https://images.unsplash.com/photo-1612531386530-97286d97c2d2?auto=format&fit=crop&w=700&q=80', 'Un cabinet de quartier pour le suivi courant des animaux de compagnie.', array['Consultation — dès 42 TND','Conseils préventifs','Suivi de croissance'], 'Lun–Sam · 09:00–17:00', '+216 70 000 505', 'published'),
  ('00000000-0000-4000-8000-000000000205', 'Le Panier de Minou', 'Animalerie', 'Sfax', 'https://images.unsplash.com/photo-1589924691995-400dc9ecc119?auto=format&fit=crop&w=700&q=80', 'Alimentation, jouets et accessoires choisis pour chiens et chats.', array['Alimentation et hygiène','Accessoires','Conseils en boutique'], 'Lun–Sam · 08:30–18:30', '+216 74 000 606', 'published'),
  ('00000000-0000-4000-8000-000000000206', 'Tout Beau Toutou', 'Toilettage', 'Tunis', 'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?auto=format&fit=crop&w=700&q=80', 'Un toilettage attentif avec une approche calme et adaptée.', array['Bain — dès 30 TND','Brossage — dès 18 TND','Coupe selon le pelage'], 'Mar–Sam · 09:00–18:00', '+216 71 000 707', 'published')
on conflict (id) do update set
