insert into public.articles (id, title, tag, body, status) values
  ('00000000-0000-4000-8000-000000000301', 'Les bonnes questions avant d’adopter', 'ADOPTION · 5 MIN', 'Adopter, c’est accueillir un compagnon pour toute sa vie. Avant la rencontre, pensez à votre rythme quotidien, à votre logement et au temps que vous pourrez lui consacrer. Échangez avec le refuge sur son tempérament, son histoire connue et ses besoins. Prévoyez un budget pour l’alimentation, les soins et les imprévus. Laissez à l’animal le temps de prendre ses marques.', 'published'),
  ('00000000-0000-4000-8000-000000000302', 'Préparer la maison pour un chat', 'BIEN-ÊTRE · 4 MIN', 'Un chat s’installe plus facilement lorsqu’il dispose d’un endroit calme où se cacher et se reposer. Installez sa litière loin de ses gamelles, proposez de l’eau fraîche et quelques espaces en hauteur. Vérifiez les fenêtres et rangez les plantes ou petits objets qui pourraient présenter un risque. Gardez une routine douce et laissez-le explorer à son propre rythme.', 'published'),
  ('00000000-0000-4000-8000-000000000303', 'Les premières promenades du chiot', 'CHIENS · 3 MIN', 'Les premières sorties sont des moments de découverte. Choisissez un endroit calme, gardez les promenades courtes et récompensez les comportements sereins. Laissez votre chiot renifler et observer sans le presser. De l’eau, un harnais bien ajusté et une progression adaptée à son âge rendent chaque sortie plus agréable. Pour les questions de santé, demandez conseil à un vétérinaire.', 'published'),
  ('00000000-0000-4000-8000-000000000304', 'Bien choisir les repas de son chat', 'ALIMENTATION · 4 MIN', 'Les besoins alimentaires varient selon l’âge, l’activité et l’état de santé de chaque chat. Proposez de l’eau propre à plusieurs endroits et gardez des horaires réguliers. Lisez les indications des aliments et demandez un avis vétérinaire si vous souhaitez changer son régime, surtout en cas de problème de santé.', 'published'),
  ('00000000-0000-4000-8000-000000000305', 'Une routine d’hygiène tout en douceur', 'SOINS · 3 MIN', 'Des gestes courts et réguliers aident votre compagnon à rester à l’aise : brossage adapté au pelage, vérification des oreilles et entretien des griffes si nécessaire. Habituez-le progressivement avec des récompenses et arrêtez s’il montre du stress. Un vétérinaire ou un toiletteur peut vous montrer les bons gestes.', 'published'),
  ('00000000-0000-4000-8000-000000000306', 'Les premiers jours dans un nouveau foyer', 'ADOPTION · 5 MIN', 'Après une adoption, gardez les premiers jours simples et prévisibles. Préparez un coin tranquille avec couchage, eau et nourriture, puis laissez votre compagnon découvrir le logement sans le forcer. Une routine stable l’aide à prendre confiance. Les refuges connaissent souvent ses habitudes et peuvent partager des conseils utiles.', 'published')
on conflict (id) do update set
  title = excluded.title, tag = excluded.tag, body = excluded.body,
  status = excluded.status;
